        assertTrue(Gt06ProtocolDecoder.decodeGps(position, Unpooled.copiedBuffer("GPS_DATA".getBytes(StandardCharsets.UTF_8)), true, true, true, TimeZone.getDefault()));
        assertFalse(Gt06ProtocolDecoder.decodeGps(position, Unpooled.copiedBuffer("GPS_DATA".getBytes(StandardCharsets.UTF_8)), false, false, false, TimeZone.getDefault()));
    }

